import numpy as np
import pandas as pd
from abc import ABC

from common.utils.time import unix_to_timestamps, timestamp_to_unix
from common.utils.slicing import soft_select
from server.storage.base import DataReader, RCSBaseWriter


class StimSpec(ABC):

    group_name = "Settings"
    dataset_name = "StimSettings"
    time_name = "StimTimestamps"


class StimReader(StimSpec, DataReader):
    """"""

    #: Data types of the last dimension
    data_types = [
        float, float, float, 'S', str, str, str, str, str
    ]

    def read(self):
        dataset = super(StimReader, self).read()
        dtypes = {}
        n_loops = 0
        for i, col in enumerate(dataset.columns):
            try:
                this_type = self.data_types[i - n_loops * len(self.data_types)]
            except IndexError:
                n_loops += 1
                this_type = self.data_types[i - n_loops * len(self.data_types)]
            dtypes[col] = this_type
        return dataset.astype(dtypes)


class StimWriter(StimSpec, RCSBaseWriter):
    """"""
    chunk_spec = (None, )
    dim_names = ['Time', 'Side', 'Parameter']
    dim_labels = [
        ['Replace', 'With', 'Timestamps'],
        ['Left', 'Right'],
        [
            'Stim Amplitude', 'Stim Freq', 'Pulse Width',
            'Adaptive Mode', 'Adaptive State', 'Stim Flags',
            'Stim Mode', 'Positive Lead', 'Negative Lead'
        ]
    ]

    @classmethod
    def from_sources(cls, left_source, right_source, target_loc, filename=None):
        """"""
        w = super(StimWriter, cls).from_sources(left_source, right_source, target_loc, filename)
        w._soft_write = True
        return w

    @staticmethod
    def determine_electrodes(parsed):
        """
        Parse the electrode settings out of the active stim program

        There are four possible categories of configurations. Realistically only ever expect the first 3
          - Monopolar: case and one negative electrode
              ex: 'c+2-'
          - Dual Monopolar: case is positive and two negative electrodes
              ex: 'c+2-3-'
          - Bipolar:  exactly one pair of positive/negative electrodes on the lead
              ex: '1+3-'
          - Dual Bipolar: more than exactly one positive or negative electrode on the lead
              ex: '1+2-3+4-'  or  '2+1-3-'  or   '1+3+2-'
        """
        negative = ', '.join(parsed.group(2).split('-'))
        if 'c' in parsed.group(1):
            positive = 'Case'
            stim_type = 'Dual Monopolar' if ',' in negative else 'Monopolar'
        else:
            positive = ', '.join(parsed.group(1).split('+'))
            stim_type = 'Dual Bipolar' if ',' in negative else 'Bipolar'
        return positive, negative, stim_type

    @staticmethod
    def determine_params(full_side):
        """
        Combine all available data into one stream and parse out 'True' settings.
        This primarily consists of real stim value and cleaning up redundant columns


        """
        # Determine the Stim Amplitude and Frequency for all the timepoints
        stim_params = {'Stim Amplitude': [], 'Stim Freq': []}
        for i, row in full_side.iterrows():
            # Determine stim amplitude, preferring adaptive settings if available
            try:
                if row['therapy_status'] == 'On':
                    if row['Adaptive Mode'] == 'Embedded':
                        amplitude = row[f'CurrentProgramAmplitudesInMilliamps_{row["active_program"]}']
                    else:
                        amplitude = row['target_amp']
                elif row['therapy_status'] == 'Off':
                    amplitude = 0
                else:
                    amplitude = np.nan
            except KeyError:
                amplitude = row['target_amp']
            stim_params['Stim Amplitude'].append(amplitude)

            # Determine stim rate, prefering adaptive settings if available
            try:
                freq = row['StimRateInHz'] if row['Adaptive Mode'] == 'Embedded' else row['target_rate']
            except KeyError:
                freq = row['target_rate']
            stim_params['Stim Freq'].append(freq)

        # Build a new dataframe of just the relevant columns in the original data, filling with NaN if necessary
        stim_params = pd.DataFrame.from_dict(stim_params)
        stim_params.index = full_side.index
        subset = pd.DataFrame.from_dict({
            'Pulse Width': soft_select(full_side, 'pulse_width'),
            'Adaptive Mode': soft_select(full_side, 'adaptiveMode'),
            'Adaptive State': soft_select(full_side, 'CurrentAdaptiveState'),
            'Stim Flags': soft_select(full_side, 'StimFlags'),
            'Stim Mode': soft_select(full_side, 'stim_type'),
            'Positive Lead': soft_select(full_side, 'positive'),
            'Negative Lead': soft_select(full_side, 'negative')
        })
        ready_side = pd.concat([stim_params, subset], axis=1)

        return ready_side

    def prep_side(self, side_source, side_settings):

        try:
            # Try loading existing timestamps if they are available
            with self.open_file() as datafile:
                times = datafile[self.group_name][self.time_name][:] * 1000
        except (FileNotFoundError, KeyError):
            lims = unix_to_timestamps([
                int(side_settings['recording_settings'][0]['start']),
                int(side_settings['recording_settings'][-1]['end'])
            ])
            times = timestamp_to_unix(
                pd.date_range(start=lims[0], end=lims[1], freq=f'0.2S')
            ) * 1000
        else:
            self._soft_write = True  # Used existing timestamps, don't write these later

        time_options = [times]
        to_combine = []
        # Load the adaptive stim data if available.
        # If adaptive is on, this is the true source of amplitude and stim rate
        try:
            adaptive = pd.read_csv(os.path.join(side_source, 'AdaptiveStim.csv'),
                                   index_col=0, usecols=[0, 1, 2, 3, 4, 5, 8, 9, 14], )
        except FileNotFoundError:
            pass
        else:
            time_options.append(adaptive.index)
            to_combine.append(adaptive)

        # Load the stim mode changes if available.
        # Primary purpose is to determine whether adaptive was on or off at each time point
        try:
            stim_modes = pd.read_csv(os.path.join(side_source, 'StimModeChanges.csv'), usecols=[0, 2], index_col=0)
        except FileNotFoundError:
            pass
        else:
            time_options.append(stim_modes.index)
            to_combine.append(stim_modes)

        # Load the StimLog.csv. Must be available
        # Primary purpose is to determine StimProgram, Group, and use this to reconstruct electrodes used, stim mode,
        # pulse width. Additionaly, if adaptive is off, this allows us to interpret stim rate and amplitude

        stim_log = pd.read_csv(os.path.join(side_source, 'StimLog.csv'),
                               usecols=[0, 1, 3, 4, 5, 6, 7], index_col=0)

        param_parse = re.compile(r'([c0-9]{1,3})\+([0-9-]{1,3})-, ([0-9.]*)mA, ([0-9]+)us, ([0-9.]+)Hz')
        stim_settings = {
            'active_group': [], 'active_program': [], 'therapy_status': [],
            'target_amp': [], 'target_rate': [], 'pulse_width': [],
            'stim_type': [], 'positive': [], 'negative': []}
        for i, stim in stim_log.iterrows():
            progs = np.array([stim[f'stimParams_prog{i}'] for i in range(1, 4+1)])
            active_prog = np.flatnonzero(progs != 'Disabled')[0] + 1
            parsed = re.search(param_parse, stim[f'stimParams_prog{active_prog}'])
            positive, negative, stim_type = self.determine_electrodes(parsed)

            stim_settings['active_group'].append(stim['activeGroup'])
            stim_settings['therapy_status'].append(stim['therapyStatusDescription'])
            stim_settings['active_program'].append(active_prog)
            stim_settings['target_amp'].append(parsed.group(3))
            stim_settings['target_rate'].append(parsed.group(5))
            stim_settings['pulse_width'].append(parsed.group(4))
            stim_settings['stim_type'].append(stim_type)
            stim_settings['negative'].append(negative)
            stim_settings['positive'].append(positive)

        stim_settings = pd.DataFrame.from_records(stim_settings, index=stim_log.index)
        to_combine.append(stim_settings)
        time_options.append(stim_settings.index)

        # Find the widest meaningful set of times to re-index all these data streams onto
        all_times = np.concatenate(time_options)
        lims = unix_to_timestamps([min(all_times), max(all_times)])
        times = timestamp_to_unix(
            pd.date_range(start=lims[0], end=lims[1], freq=f'0.2S')
        ) * 1000
        combinable = [dataset.reindex(times, method='pad') for dataset in to_combine]

        # Combine all data streams and select out meaningful data to return
        full_side = pd.concat(combinable, axis=1)
        ready_side = self.determine_params(full_side)
        return ready_side

    def prep_data(self):
        self.left_data = self.prep_side(self.left_source, self.left_settings)
        self.right_data = self.prep_side(self.right_source, self.right_settings)
        timestamps, ready_data = super(StimWriter, self).prep_data()
        return timestamps, ready_data.astype('S')

    def prep_attributes(self):
        return super(StimWriter, self).prep_attributes()


class AdaptiveSpec(ABC):

    group_name = "Settings"
    dataset_name = "AdaptiveSettings"
    time_name = "AdaptiveTimestamps"


class AdaptiveReader(AdaptiveSpec, DataReader):
    """"""


class AdaptiveWriter(AdaptiveSpec, RCSBaseWriter):
    """"""
    point_shape = (2, 2, 9)
    chunk_spec = (None,)
    dim_names = ['Time', 'Side', 'Linear Discriminator', 'Parameter']
    dim_labels = [
        ['Replace', 'With', 'Timestamps'],
        ['Left', 'Right'],
        ['LD0', 'LD1'],
        [
            'Detection Status', 'Fixed Decimal', 'Low Threshold', 'High Threshold', 'Output',
            'Feature Input 1', 'Feature Input 2', 'Feature Input 3', 'Feature Input 4',
        ]
    ]

    matlab_names = [
            '{}DetectionStatus', '{}_fixedDecimalPoint', '{}_lowThreshold', '{}_highThreshold', '{}_output',
            '{}_featureInputs_1', '{}_featureInputs_2', '{}_featureInputs_3', '{}_featureInputs_4',
        ]

    def __init__(self, target):
        super(AdaptiveWriter, self).__init__(target)
        self.stream_attributes = {}

    @classmethod
    def from_sources(cls, left_source, right_source, target_loc, filename='AdaptiveStim.csv'):
        """"""
        return super(AdaptiveWriter, cls).from_sources(left_source, right_source, target_loc, filename)

    def select_side(self, side_data):
        """Select all the data for both the LDs in one side"""
        to_stack = []
        for ld in ['Ld0', 'Ld1']:
            src_names = [name.format(ld) for name in self.matlab_names]
            ld_data = pd.DataFrame.from_dict({
                label: side_data[src_names[i]] for i, label in enumerate(self.dim_labels[-1])
            })
            ld_data.columns = pd.MultiIndex.from_tuples(
                zip([ld] * len(ld_data.columns), ld_data.columns)
            )
            to_stack.append(ld_data)
        return pd.concat(to_stack, axis=1)

    def prep_data(self):
        self.left_data = self.select_side(self.left_data)
        self.right_data = self.select_side(self.right_data)

        return super(AdaptiveWriter, self).prep_data()

    def prep_attributes(self):
        base_attrs = super(AdaptiveWriter, self).prep_attributes()

        self.stream_attributes.update({
            'Left LD0 Settings': self.left_settings['detector_settings']['LD0'],
            'Left LD1 Settings': self.left_settings['detector_settings']['LD1'],
            'Right LD0 Settings': self.right_settings['detector_settings']['LD0'],
            'Right LD1 Settings': self.right_settings['detector_settings']['LD1']
        })
        return base_attrs


